func isLoopback(addr string) bool {
	host, _, err := net.SplitHostPort(addr)
	if err != nil {
		return false
	}
	if host == "localhost" {
		return true
	}
	ip := net.ParseIP(host)
	return ip != nil && ip.IsLoopback()
}

// newServer builds the API server; custom uploads are enabled only with ownRegions.
func newServer(parser *jsonParser.Parser, ownRegions bool) *API.Server {
	srv := &API.Server{Parser: parser}
	if ownRegions {
		srv.Custom = custom.NewStore()
	}
	return srv
}

func main() {
	ownRegions := flag.Bool("own-regions", false, "accept user-uploaded regions, variables and missions (/api/custom/*)")
	flag.Parse()

	dataDir := os.Getenv("DATA_DIR")
	if dataDir == "" {
		dataDir = "data" // relative to where the binary runs
	}
	addr := os.Getenv("ADDR")
	if addr == "" {
		addr = ":8080"
		if *ownRegions {
			addr = "127.0.0.1:8080"
		}
	}
	origin := os.Getenv("ALLOWED_ORIGIN") // empty = any localhost origin

	parser, err := jsonParser.New(dataDir)
	if err != nil {
		log.Fatal(err)
	}

	srv := newServer(parser, *ownRegions)
	if *ownRegions && !isLoopback(addr) {
		log.Printf("WARNING: --own-regions on %s: anyone who can reach this address can upload data", addr)
	}

	httpSrv := &http.Server{
		Addr:              addr,
		Handler:           cors(origin, srv.Routes()),
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       15 * time.Second,
		WriteTimeout:      15 * time.Second,
	}
	originMsg := origin
	if originMsg == "" {
		originMsg = "any localhost"
	}
	log.Printf("listening on %s (data: %s, own-regions: %v, CORS origin: %s)", addr, dataDir, *ownRegions, originMsg)
	log.Fatal(httpSrv.ListenAndServe())
}
